@GuardedBy("lock")
private List<TimelineObjectHolder<VersionType, ObjectType>> lookup(Interval interval, Partitions completeness)
{
  List<TimelineObjectHolder<VersionType, ObjectType>> retVal = new ArrayList<>();
  NavigableMap<Interval, TimelineEntry> timeline;
  if (completeness == Partitions.INCOMPLETE_OK) {
    timeline = incompletePartitionsTimeline;
  } else {
    timeline = completePartitionsTimeline;
  }

  final DateTime queryStart = interval.getStart();
  final DateTime queryEnd = interval.getEnd();
  final boolean queryComparableAsString = Intervals.canCompareEndpointsAsStrings(interval);

  for (Entry<Interval, TimelineEntry> entry : timeline.entrySet()) {
    Interval timelineInterval = entry.getKey();
    TimelineEntry val = entry.getValue();
    PartitionHolder<ObjectType> partitionHolder = val.getPartitionHolder();

    // exclude empty partition holders (i.e. tombstones) since they do not add value
    // for higher level code...they have no data rows...
    boolean includeHolder = true;
    if (skipObjectsWithNoData) {
      includeHolder = false;
      for (ObjectType payload : partitionHolder.payloads()) {
        if (payload.hasData()) {
          includeHolder = true;
          break;
        }
      }
    }

    if (includeHolder) {
      if (timelineInterval.overlaps(interval)) {
        Interval holderInterval = timelineInterval;
        Interval holderTrueInterval = val.getTrueInterval();
        VersionType holderVersion = val.getVersion();
        PartitionHolder<ObjectType> visibleChunks =
            PartitionHolder.copyWithOnlyVisibleChunks(partitionHolder);
        retVal.add(
            new TimelineObjectHolder<>(
                holderInterval,
                holderTrueInterval,
                holderVersion,
                visibleChunks
            )
        );
      }
    }
  }

  if (retVal.isEmpty()) {
    return retVal;
  }

  TimelineObjectHolder<VersionType, ObjectType> firstEntry = retVal.get(0);
  Interval firstInterval = firstEntry.getInterval();
  if (interval.overlaps(firstInterval)) {
    DateTime firstStart = firstInterval.getStart();
    DateTime firstEnd = firstInterval.getEnd();
    DateTime clippedStart = firstStart;
    if (queryComparableAsString) {
      if (queryStart.toString().compareTo(firstStart.toString()) > 0) {
        clippedStart = queryStart;
      }
    } else if (queryStart.isAfter(firstStart)) {
      clippedStart = queryStart;
    }
    if (clippedStart.getMillis() != firstStart.getMillis()) {
      Interval clippedFirstInterval = new Interval(clippedStart, firstEnd);
      VersionType firstVersion = firstEntry.getVersion();
      Interval firstTrueInterval = firstEntry.getTrueInterval();
      PartitionHolder<ObjectType> firstObject = firstEntry.getObject();
      retVal.set(
          0,
          new TimelineObjectHolder<>(
              clippedFirstInterval,
              firstTrueInterval,
              firstVersion,
              firstObject
          )
      );
    }
  }

  TimelineObjectHolder<VersionType, ObjectType> lastEntry = retVal.get(retVal.size() - 1);
  Interval lastInterval = lastEntry.getInterval();
  if (interval.overlaps(lastInterval)) {
    DateTime lastStart = lastInterval.getStart();
    DateTime lastEnd = lastInterval.getEnd();
    DateTime clippedEnd = lastEnd;
    if (queryComparableAsString) {
      if (queryEnd.toString().compareTo(lastEnd.toString()) < 0) {
        clippedEnd = queryEnd;
      }
    } else if (queryEnd.isBefore(lastEnd)) {
      clippedEnd = queryEnd;
    }
    if (clippedEnd.getMillis() != lastEnd.getMillis()) {
      Interval clippedLastInterval = new Interval(lastStart, clippedEnd);
      VersionType lastVersion = lastEntry.getVersion();
      Interval lastTrueInterval = lastEntry.getTrueInterval();
      PartitionHolder<ObjectType> lastObject = lastEntry.getObject();
      retVal.set(
          retVal.size() - 1,
          new TimelineObjectHolder<>(
              clippedLastInterval,
              lastTrueInterval,
              lastVersion,
              lastObject
          )
      );
    }
  }

  return retVal;
}

public class TimelineEntry
{
  private final Interval trueInterval;
  private final VersionType version;
  private final PartitionHolder<ObjectType> partitionHolder;

  TimelineEntry(Interval trueInterval, VersionType version, PartitionHolder<ObjectType> partitionHolder)
  {
    this.trueInterval = Preconditions.checkNotNull(trueInterval);
    this.version = Preconditions.checkNotNull(version);
    this.partitionHolder = Preconditions.checkNotNull(partitionHolder);
  }

  Interval getTrueInterval()
  {
    return trueInterval;
  }

  public VersionType getVersion()
  {
    return version;
  }

  public PartitionHolder<ObjectType> getPartitionHolder()
  {
    return partitionHolder;
  }

  @Override
  public boolean equals(Object o)
  {
    if (this == o) {
      return true;
    }

    if (o == null || getClass() != o.getClass()) {
      return false;
    }

    final TimelineEntry that = (TimelineEntry) o;

    if (!this.trueInterval.equals(that.trueInterval)) {
      return false;
    }

    if (!this.version.equals(that.version)) {
      return false;
    }

    if (!this.partitionHolder.equals(that.partitionHolder)) {
      return false;
    }

    return true;
  }

  @Override
  public int hashCode()
  {
    return Objects.hash(trueInterval, version, partitionHolder);
  }
}

